@extends('admin.layout') @section('title',$pageType) @section('heading',$pageType.' Management') @push('styles')<style>.section{margin-bottom:18px}.row{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:center;padding:15px 0;border-bottom:1px solid #eef0f3}.row:last-child{border:0}.meta{font-size:12px;color:#667085;margin-top:4px}.form-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px}.wide{grid-column:1/-1}.status{display:inline-flex;padding:5px 9px;border-radius:99px;background:#eef1ff;color:#4459c5;font-size:11px;font-weight:850}@media(max-width:700px){.row,.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>@endpush @section('content')<section class="card">@forelse($workers as $user)<div class="row"><div><strong>{{ $user->name }}</strong><div class="meta">{{ $user->email }} · Joined {{ $user->created_at->format('M d, Y') }}</div></div><span class="status">{{ ucfirst($user->role) }}</span><strong>{{ ucfirst($user->status) }}</strong><form method="POST" action="{{ route('admin.users.status',$user) }}">@csrf @method('PATCH')<select class="input" name="status"><option value="active" @selected($user->status==='active')>Active</option><option value="suspended" @selected($user->status==='suspended')>Suspended</option><option value="blocked" @selected($user->status==='blocked')>Blocked</option></select><button class="btn" style="margin-top:6px;width:100%">Update</button></form></div>@empty<p class="muted">No accounts found.</p>@endforelse</section><div style="margin-top:16px">{{ $workers->links() }}</div>@endsection